function shell(page){
 const canonical=url(page.file==='index.html'?'':page.file);
 const areas=['Kent','Sevenoaks','Tonbridge','Tunbridge Wells'].map(name=>({'@type':name==='Kent'?'AdministrativeArea':'Place',name}));
 const pageType=page.pageType || ({'about.html':'AboutPage','contact.html':'ContactPage','guides.html':'CollectionPage'}[page.file]) || 'WebPage';
 const graph=[
  {'@type':'Organization','@id':url('#studio'),name:config.name,url:config.url,description:config.description,logo:{'@id':url('#logo')},areaServed:areas,...(config.email?{email:config.email,contactPoint:{'@type':'ContactPoint',contactType:'customer enquiries',email:config.email,availableLanguage:'English'}}:{})},
  {'@type':'ImageObject','@id':url('#logo'),url:url('assets/logo.svg'),contentUrl:url('assets/logo.svg'),width:600,height:160,caption:config.name},
  {'@type':'WebSite','@id':url('#website'),url:config.url,name:config.name,inLanguage:'en-GB',publisher:{'@id':url('#studio')}},
  {'@type':pageType,'@id':canonical+'#page',url:canonical,name:page.title,description:page.description,inLanguage:'en-GB',isPartOf:{'@id':url('#website')},publisher:{'@id':url('#studio')},about:{'@id':url('#studio')},...(page.service?{mainEntity:{'@id':canonical+'#service'}}:{}),...(page.file!=='index.html'?{breadcrumb:{'@id':canonical+'#breadcrumb'}}:{})}
 ];
 if(page.file!=='index.html'){
  const crumbs=[{name:'Home',item:config.url},...(page.parents||[]).map(parent=>({name:parent.name,item:url(parent.file)})),{name:page.breadcrumb || page.title.split('|')[0].trim(),item:canonical}];
  graph.push({'@type':'BreadcrumbList','@id':canonical+'#breadcrumb',itemListElement:crumbs.map((crumb,i)=>({'@type':'ListItem',position:i+1,...crumb}))});
 }
 if(page.service)graph.push({'@type':'Service','@id':canonical+'#service',name:page.service,serviceType:page.service,description:page.description,provider:{'@id':url('#studio')},areaServed:areas,url:canonical,mainEntityOfPage:{'@id':canonical+'#page'}});
 const related=relatedContent(page);
 const body=page.body.includes('<section class="closing">')?page.body.replace('<section class="closing">',related+'<section class="closing">'):page.body+related;
 return `<!doctype html>\n<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#252522"><title>${esc(page.title)}</title><meta name="description" content="${esc(page.description)}"><link rel="canonical" href="${canonical}"><link rel="describedby" type="text/markdown" href="${url('llms.txt')}">${page.noindex?'<meta name="robots" content="noindex,follow">':'<meta name="robots" content="index,follow,max-image-preview:large">'}<meta property="og:type" content="website"><meta property="og:site_name" content="Clearly Online"><meta property="og:locale" content="en_GB"><meta property="og:title" content="${esc(page.title)}"><meta property="og:description" content="${esc(page.description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${url('assets/social-card.png')}"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Clearly Online. Good at what you do. Look the part online."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(page.title)}"><meta name="twitter:description" content="${esc(page.description)}"><meta name="twitter:image" content="${url('assets/social-card.png')}"><meta name="twitter:image:alt" content="Clearly Online. Good at what you do. Look the part online."><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/manrope-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="styles.min.css?v=${cssVersion}"><script src="script.min.js?v=${jsVersion}" defer></script><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@graph':graph}).replace(/</g,'\\u003c')}</script></head><body><a class="skip" href="#main">Skip to content</a><div class="local-bar">Independent web design <span>·</span> Sevenoaks & Kent <span class="bar-extra">· Clear thinking. Clearly online.</span></div><header><div class="container header-inner"><a class="logo" href="./" aria-label="Clearly Online home">Clearly Online<span aria-hidden="true">↗</span></a><button class="menu" aria-controls="navigation" aria-expanded="false" hidden>Menu <span aria-hidden="true">+</span></button><nav id="navigation" aria-label="Main navigation">${websiteNavigation(page)}${navItems.map(([path,label])=>`<a href="${path}"${page.file===path?' aria-current="page"':''}>${label}</a>`).join('')}${link('contact.html',"Let's talk",'nav-cta')}</nav></div></header><main id="main" tabindex="-1">${body}</main><footer><div class="container"><div class="footer-top"><div><a class="logo" href="./">Clearly Online<span aria-hidden="true">↗</span></a><p>Good work. Clearly presented.<br>Independent web design in Sevenoaks & Kent.</p></div><div class="footer-links"><a href="web-design.html">Website design</a><a href="local-seo.html">Local SEO</a><a href="website-care.html">Hosting & care</a><a href="pricing.html">Prices explained</a><a href="websites-for-trades.html">For trades</a><a href="websites-for-appointments.html">For appointment businesses</a><a href="websites-for-professionals.html">For professional services</a><a href="guides.html">Website guides</a><a href="about.html">About the studio</a><a href="contact.html">Start a conversation</a></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Clearly Online</span><a href="privacy.html">Website privacy</a><a href="#main">Back to top ↑</a></div></div></footer></body></html>\n`;
}
// No trademark registration is claimed: the wordmark uses a directional mark.
for(const page of pages)writeFileSync(page.file,shell(page));
writeFileSync('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.filter(p=>!p.noindex).map(p=>`<url><loc>${url(p.file==='index.html'?'':p.file)}</loc></url>`).join('')}</urlset>\n`);
writeFileSync('robots.txt',`User-agent: *\nAllow: /\nSitemap: ${url('sitemap.xml')}\n`);
writeFileSync('llms.txt',`# Clearly Online\n\n> Independent web design studio near Sevenoaks, Kent. Clearly Online builds clear websites for local trades and small businesses, with practical local SEO, hosting and ongoing care.\n\n## Start here\n\n- [Homepage](${config.url}): The studio, services, prices and how to enquire.\n- [Website design](${url('web-design.html')}): Website builds, redesigns, quote forms and booking integrations.\n- [Pricing](${url('pricing.html')}): Guide package prices, optional hosting and care, exclusions and cost comparison.\n- [About Clearly Online](${url('about.html')}): The studio's mission and approach.\n- [Contact](${url('contact.html')}): Public email address and an optional email draft tool.\n\n## Who the websites are for\n\n- [Trades and home services](${url('websites-for-trades.html')}): Service areas, job examples and useful quote requests.\n- [Appointment-led businesses](${url('websites-for-appointments.html')}): Service clarity, booking tools and customer questions.\n- [Local professional services](${url('websites-for-professionals.html')}): Explaining complex work, trust and introductory enquiries.\n\n## Other services\n\n- [Local SEO](${url('local-seo.html')}): Search foundations and optional ongoing work.\n- [Website care](${url('website-care.html')}): Hosting, maintenance and support.\n\n## Website planning guides\n\n${pages.filter(p=>['guides.html','website-cost-guide.html','website-brief-checklist.html'].includes(p.file)).map(p=>`- [${p.title.split('|')[0].trim()}](${url(p.file)}): ${p.description}`).join('\n')}\n\n## Key facts\n\n- The studio serves businesses near Sevenoaks and across Kent; projects can be reviewed remotely.\n- Website build guide prices are Starter £400, Business £500, and Growth from £600.\n- Optional hosting and routine website care are £49 per month. Content changes, third-party charges and new features are separate unless quoted.\n- The quote determines final scope, tax treatment, third-party costs and contractual terms.\n- No customer ratings, awards, quantified results or search ranking guarantees are claimed.\n- Public contact: ${config.email || 'See contact page for current details'}. The website prepares an email draft; sending happens in the visitor's email app.\n\n## Optional\n\n- [Website privacy](${url('privacy.html')}): Information about this website's current data handling.\n`);
writeFileSync('404.html',`<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Page not found | Clearly Online</title><link rel="stylesheet" href="${url('styles.min.css')}"></head><body><main class="page-hero"><div class="container"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>Wrong turn.<br><span>Easy fix.</span></h1><p>This page may have moved or the address may be incorrect.</p><a class="button accent" href="${config.url}">Back to Clearly Online ↗</a></div></main></body></html>`);
console.log(`Built ${pages.length} pages, sitemap, robots.txt and 404 for ${config.url}`);
